// SUPPORT EMAIL RAG RESPONDER — CONFIG
// Everything you might want to change lives in this one node. Nothing else in either
// workflow needs editing.
//
// The same config node ships in BOTH workflows ("01 answer support email" and
// "02 load knowledge base"). build.js regenerates both from this one file, and validate.js
// fails if they drift apart, so you never paste it between them by hand.
//
// No API key is written here. OpenAI, Pinecone and Gmail are connected as n8n credentials on
// the nodes named [cred] ..., so the exported JSON never carries a secret. The switches below
// only say whether those credentials are in place.
//
// With everything below left as shipped, both workflows run end to end on the built-in demo
// emails and demo knowledge base, and nothing is sent, embedded or written anywhere.

// ---------------------------------------------------------------- Who is answering
const COMPANY_NAME = 'Demo Agency';
// How every automated reply is signed.
const SIGNATURE    = 'The Demo Agency support team';
// Where escalations go: the person or shared inbox that picks up what the workflow will not
// answer on its own. Blank -> escalations are built and shown, never sent.
const SUPPORT_TEAM_EMAIL = '';
// Your own sending addresses. Mail from these is never answered, so the workflow cannot reply
// to its own replies.
const OWN_ADDRESSES = [];

// ---------------------------------------------------------------- OpenAI
// true once an OpenAI credential is attached to the three [cred] OpenAI nodes in 01 and the
// one in 02. false -> classification runs on the keyword rules below, and replies are written
// from the matched knowledge with a fixed template. The run still completes.
const USE_OPENAI         = false;
const OPENAI_CHAT_MODEL  = 'gpt-4o-mini';
const OPENAI_EMBED_MODEL = 'text-embedding-3-small';
const EMBED_DIMENSIONS   = 1536;     // must match the Pinecone index

// ---------------------------------------------------------------- Pinecone
// The index host from the Pinecone console, e.g. https://support-kb-abc123.svc.us-east-1.pinecone.io
// The API key goes in an n8n "Header Auth" credential (name: Api-Key) on the [cred] Pinecone
// nodes. Blank host -> the built-in demo knowledge base below is searched instead.
const PINECONE_INDEX_HOST = '';
const PINECONE_NAMESPACE  = 'support-kb';
const TOP_K               = 4;       // how many knowledge chunks are retrieved per email

// ---------------------------------------------------------------- The two gates
// The workflow only answers when it is sure on BOTH counts. Anything below either floor goes
// to a person, never to a guess.
//
// Classification: how confident the classifier must be that this is (or is not) a support
// request before acting on it.
const MIN_CLASSIFY_CONFIDENCE = 0.6;
// Knowledge: the best retrieved chunk must score at least this. Pinecone returns cosine
// similarity (0..1); the demo knowledge base uses a simpler word-overlap score, so it has its
// own floor.
const MIN_MATCH_SCORE      = 0.75;
const DEMO_MIN_MATCH_SCORE = 0.3;

// Keyword rules. They always run: with USE_OPENAI = false they ARE the classifier, and with it
// on they are the fallback when the model call fails or its answer does not parse.
const SUPPORT_WORDS = ['help', 'issue', 'problem', 'error', 'not working', 'broken', "can't", 'cannot',
  'unable', 'how do i', 'how can i', 'password', 'login', 'log in', 'access', 'invoice', 'billing',
  'payment', 'report', 'dashboard', 'account', 'question', 'support', 'reset', 'update my', 'change my'];
const NOT_SUPPORT_WORDS = ['partnership', 'guest post', 'backlink', 'seo services', 'our services',
  'sponsorship', 'collaboration', 'newsletter', 'unsubscribe', 'webinar', 'special offer',
  'limited time', 'book a demo with us', 'we help agencies'];
// Intents that always go to a person, however good the knowledge match. The email most likely
// to be made worse by an automated answer is the angry one.
const HANDOFF_WORDS = ['refund', 'chargeback', 'complaint', 'unacceptable', 'lawyer', 'legal',
  'cancel my contract', 'cancel our contract', 'terminate', 'third time', 'furious', 'disappointed'];
const HANDOFF_INTENTS = ['complaint', 'refund', 'legal', 'cancellation'];

// ---------------------------------------------------------------- Knowledge base (workflow 02)
// Public URLs of help pages or docs to load into Pinecone. Blank -> the demo knowledge base
// below is chunked and shown instead.
const DOC_URLS      = [];
const CHUNK_WORDS   = 160;
const CHUNK_OVERLAP = 30;

// ---------------------------------------------------------------- Safety switch
// TEST_RUN = true and TEST_EMAIL blank -> PREVIEW. Every reply and escalation is built in full
// and shown on a STOP node; nothing is sent, nothing is upserted.
// TEST_RUN = true and TEST_EMAIL set  -> TEST. Replies and escalations are sent, but all of them
// to TEST_EMAIL, at most TEST_CAP per run, marked [TEST]. Knowledge can be upserted.
// TEST_RUN = false                     -> LIVE. Replies go to the customer, in their thread.
const TEST_RUN   = true;
const TEST_EMAIL = '';
const TEST_CAP   = 3;
// Hard ceiling on customer replies in one run, enforced in code.
const REPLY_CAP_PER_RUN = 20;

const MODE = TEST_RUN !== true ? 'live' : (TEST_EMAIL.trim() !== '' ? 'test' : 'preview');

// ---------------------------------------------------------------- Demo data
// Invented. Used only when nothing is connected, so the whole run can be watched first.
const DEMO_KNOWLEDGE = [
  { id: 'portal-access', title: 'Logging in to the client portal',
    text: 'To reset your client portal password, open the portal login page and click "Forgot password". '
      + 'Enter the email address your account was set up with and we send a reset link that is valid for 60 minutes. '
      + 'If the link has expired, request a new one. If you no longer have access to that email address, reply to your '
      + 'account manager and we will move the login to a new address after confirming it with the account owner.' },
  { id: 'invoices', title: 'Invoices and billing',
    text: 'Invoices are issued on the 1st of each month and emailed to the billing contact on file. Payment is due '
      + 'within 14 days by bank transfer or card. You can download past invoices from Billing in the client portal. '
      + 'To change the billing contact or the company details printed on the invoice, reply with the new details '
      + 'and they will appear from the next invoice.' },
  { id: 'reporting', title: 'Monthly reports',
    text: 'Performance reports are published in the client portal by the 5th working day of each month and a link is '
      + 'emailed to the report contacts on your account. Live dashboards update daily. To add someone to the report '
      + 'emails, reply with their name and email address.' },
  { id: 'campaign-changes', title: 'Requesting campaign changes',
    text: 'Budget changes, pausing a campaign and new creative requests are handled within two working days of the '
      + 'request. Urgent pauses are actioned the same working day if requested before 3pm. Send change requests to '
      + 'support with the campaign name and the change you need.' },
  { id: 'onboarding', title: 'Onboarding a new account',
    text: 'New accounts need admin access to the ad accounts, analytics and the website tag manager. Your onboarding '
      + 'checklist in the client portal lists each access request, and the first campaigns go live about ten working '
      + 'days after all access is granted.' }
];

const DEMO_EMAILS = [
  { from: 'Priya Shah <user@example.com>', subject: 'Locked out of the portal',
    text: "Hi, I can't log in to the client portal. How do I reset my password?",
    id: 'demo-msg-001', threadId: 'demo-thread-001', messageId: '<user@example.com>' },
  { from: 'Tom Reid <user@example.com>', subject: 'Re: March invoice',
    text: 'Thanks. Can you change the billing contact on our invoice to user@example.com please?',
    id: 'demo-msg-002', threadId: 'demo-thread-777', messageId: '<user@example.com>',
    inReplyTo: '<user@example.com>' },
  { from: 'Ana Lopez <user@example.com>', subject: 'TikTok Shop',
    text: 'Hello, we have a problem connecting our TikTok Shop catalogue to the product feed. Can you help?',
    id: 'demo-msg-003', threadId: 'demo-thread-003', messageId: '<user@example.com>' },
  { from: 'Growth Partners <hello@example.com>', subject: 'Partnership opportunity',
    text: 'We help agencies scale with white-label SEO services. Interested in a partnership? Book a demo with us.',
    id: 'demo-msg-004', threadId: 'demo-thread-004', messageId: '<user@example.com>' },
  { from: 'Mark Evans <user@example.com>', subject: 'Report late AGAIN',
    text: 'This is the third time our monthly report is late. Frankly unacceptable, and I want a refund for this month.',
    id: 'demo-msg-005', threadId: 'demo-thread-005', messageId: '<user@example.com>' },
  { from: '', subject: '', text: '', id: 'demo-msg-006', threadId: 'demo-thread-006', messageId: '' }
];

const SETTINGS = {
  company_name:       COMPANY_NAME.trim(),
  signature:          SIGNATURE.trim(),
  support_team_email: SUPPORT_TEAM_EMAIL.trim(),
  own_addresses:      OWN_ADDRESSES.map((a) => String(a).trim().toLowerCase()).filter(Boolean),

  openai_chat_model:  OPENAI_CHAT_MODEL.trim(),
  openai_embed_model: OPENAI_EMBED_MODEL.trim(),
  embed_dimensions:   Number(EMBED_DIMENSIONS) || 1536,

  pinecone_index_host: PINECONE_INDEX_HOST.trim().replace(/\/+$/, ''),
  pinecone_namespace:  PINECONE_NAMESPACE.trim(),
  top_k:               Number(TOP_K) || 4,

  min_classify_confidence: Number(MIN_CLASSIFY_CONFIDENCE) || 0.6,
  min_match_score:         Number(MIN_MATCH_SCORE) || 0.75,
  demo_min_match_score:    Number(DEMO_MIN_MATCH_SCORE) || 0.3,

  support_words:     SUPPORT_WORDS,
  not_support_words: NOT_SUPPORT_WORDS,
  handoff_words:     HANDOFF_WORDS,
  handoff_intents:   HANDOFF_INTENTS,

  doc_urls:      DOC_URLS.map((u) => String(u).trim()).filter(Boolean),
  chunk_words:   Number(CHUNK_WORDS) || 160,
  chunk_overlap: Number(CHUNK_OVERLAP) || 0,

  test_email:        TEST_EMAIL.trim(),
  test_cap:          Number(TEST_CAP) || 3,
  reply_cap_per_run: Number(REPLY_CAP_PER_RUN) || 20,
  mode:              MODE,

  demo_knowledge: DEMO_KNOWLEDGE,
  demo_emails:    DEMO_EMAILS,

  // derived flags — the gates read these, never the raw constants
  openai_enabled:    USE_OPENAI === true,
  retrieval_enabled: USE_OPENAI === true && PINECONE_INDEX_HOST.trim() !== '',
  docs_enabled:      DOC_URLS.length > 0,
  // Replies are only sent outside preview. In test mode they are all redirected to TEST_EMAIL.
  send_enabled:      MODE !== 'preview',
  // An escalation needs somewhere to go: the team inbox live, TEST_EMAIL in test.
  alert_enabled:     MODE === 'test' || (MODE === 'live' && SUPPORT_TEAM_EMAIL.trim() !== ''),
  // Loading knowledge changes the index every reply is answered from, so preview never does it.
  upsert_enabled:    USE_OPENAI === true && PINECONE_INDEX_HOST.trim() !== '' && MODE !== 'preview'
};

// config passes the incoming payload through untouched under `incoming`, so whichever
// trigger fired, the next node reads the payload from the same place. It runs once per item.
const incoming = $input.all().length ? $input.all().map((i) => i.json || {}) : [{}];
return incoming.map((payload) => ({ json: Object.assign({}, SETTINGS, { incoming: payload }) }));

// Reads each incoming email into one shape: sender, subject, body, the Gmail message id and
// thread id (what the reply is attached to), and the RFC Message-ID header.
//
// Emails come from `config` (one item per email the Gmail trigger picked up). Run by hand,
// config carries no email, so the invented DEMO_EMAILS stand in and the whole run is visible
// with nothing connected.
//
// The Gmail trigger with "Simplify" off returns a parsed message: `from.value[0].address`,
// `text`, `html`, `headers`. With it on, `From` and `snippet`. Both are read.
const cfg = $('config').first().json;

const isReal = (p) => p && (p.id || p.threadId || p.from || p.From || p.text || p.snippet);
let emails = $input.all().map((i) => i.json.incoming).filter(isReal);
const demo = emails.length === 0;
if (demo) emails = cfg.demo_emails;

const strip = (html) => String(html || '').replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/\s+/g, ' ').trim();

function sender(p) {
  const v = p.from && p.from.value && p.from.value[0];
  if (v && v.address) return { address: v.address, name: v.name || '' };
  const raw = String((typeof p.from === 'string' ? p.from : '') || p.From || (p.headers || {}).from || '');
  const m = raw.match(/^\s*"?([^"<]*)"?\s*<([^>]+)>\s*$/);
  if (m) return { address: m[2].trim(), name: m[1].trim() };
  return { address: raw.trim(), name: '' };
}

// Quoted history below the new text would make every reply in a thread look like the first
// message again. Keep only what this sender just wrote.
function newText(body) {
  const lines = String(body).split(/\r?\n/);
  const cut = lines.findIndex((l) => /^\s*>/.test(l) || /^On .+wrote:\s*$/.test(l) || /^-{2,}\s*Original Message/i.test(l));
  return (cut === -1 ? lines : lines.slice(0, cut)).join('\n').trim();
}

return emails.map((p) => {
  const s = sender(p);
  const headers = p.headers || {};
  const body = newText(p.text || p.textPlain || strip(p.html) || p.snippet || '');
  const address = s.address.toLowerCase();
  const autoReply = /auto-replied|auto-generated/i.test(String(headers['auto-submitted'] || ''))
    || /bulk|list|junk/i.test(String(headers.precedence || ''));

  let problem = '';
  if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(address)) problem = 'no usable sender address';
  else if (!body) problem = 'empty body';
  else if (cfg.own_addresses.includes(address)) problem = 'sent from one of our own addresses';
  else if (autoReply) problem = 'an automatic or bulk message';

  return { json: {
    demo,
    from: address,
    from_name: s.name || address.split('@')[0] || '',
    subject: String(p.subject || p.Subject || headers.subject || '').trim(),
    body,
    message_id: String(p.id || ''),                   // Gmail's id: the reply is attached to this
    thread_id: String(p.threadId || ''),              // the conversation the reply must stay in
    rfc_message_id: String(p.messageId || headers['message-id'] || ''),
    in_reply_to: String(p.inReplyTo || headers['in-reply-to'] || ''),
    usable: problem === '',
    problem
  } };
});

// Emails that cannot be answered at all: no sender, no body, our own mail, or an automatic
// or bulk message. Dropped here, by name, with the reason, so the execution list shows what
// was ignored and why instead of it vanishing.
return $input.all().map((i) => ({ json: {
  outcome: 'ignored: ' + i.json.problem,
  from: i.json.from || '(none)',
  subject: i.json.subject || '(none)',
  message_id: i.json.message_id
} }));

// Builds one OpenAI chat request per email, asking for a typed classification and nothing
// else. The model never sees the knowledge base here and never writes a reply: it only sorts.
// The whole email rides along on the item so `apply the AI classification` can pair the
// answer back to it.
const cfg = $('config').first().json;

const system = [
  'You sort incoming email for the customer support desk of ' + cfg.company_name + '.',
  'Answer with a JSON object only, with exactly these keys:',
  '  "category": "support" or "not_support"  (support = an existing customer asking for help, reporting a problem or asking about their account; not_support = sales pitches, newsletters, partnership offers, spam, anything else)',
  '  "intent": one of "question", "access", "billing", "complaint", "refund", "legal", "cancellation", "other"',
  '  "handoff": true if a person should answer (angry, a complaint, refund, legal, cancelling), else false',
  '  "confidence": a number from 0 to 1',
  '  "reason": one short sentence',
  'Do not answer the email.'
].join('\n');

return $input.all().map((i) => ({ json: Object.assign({}, i.json, {
  _body: {
    model: cfg.openai_chat_model,
    temperature: 0,
    response_format: { type: 'json_object' },
    messages: [
      { role: 'system', content: system },
      { role: 'user', content: 'Subject: ' + i.json.subject + '\n\n' + i.json.body.slice(0, 6000) }
    ]
  }
}) }));

// Pairs each OpenAI answer back to its email and checks it is the shape that was asked for.
// Anything else (the call failed after its retries, the JSON does not parse, a category or
// intent outside the allowed list) falls back to the keyword rules for that email, and the
// fallback is written on the item so it is visible, not silent.
// lib-classify.js: the keyword rules and the decision that reads a classification.
// Inlined by build.js into every node that classifies, so the keyword path and the AI
// fallback can never disagree.
function keywordClassify(email, cfg) {
  const t = ' ' + (email.subject + ' ' + email.body).toLowerCase().replace(/\s+/g, ' ') + ' ';
  const hits = (list) => list.filter((w) => t.indexOf(w.toLowerCase()) !== -1);
  const sup = hits(cfg.support_words);
  const not = hits(cfg.not_support_words);
  const hand = hits(cfg.handoff_words);

  let intent = 'question';
  if (hand.some((w) => /refund|chargeback/.test(w))) intent = 'refund';
  else if (hand.some((w) => /lawyer|legal/.test(w))) intent = 'legal';
  else if (hand.some((w) => /cancel|terminate/.test(w))) intent = 'cancellation';
  else if (hand.length) intent = 'complaint';
  else if (sup.some((w) => /password|login|log in|access|reset/.test(w))) intent = 'access';
  else if (sup.some((w) => /invoice|billing|payment/.test(w))) intent = 'billing';

  if (hand.length) {
    return { category: 'support', intent, handoff: true, confidence: 0.9,
      reason: 'handoff words: ' + hand.join(', ') };
  }
  if (not.length > sup.length) {
    return { category: 'not_support', intent: 'other', handoff: false,
      confidence: Math.min(0.95, 0.6 + 0.1 * (not.length - sup.length)),
      reason: 'not-support words: ' + not.join(', ') };
  }
  if (sup.length) {
    return { category: 'support', intent, handoff: false,
      confidence: Math.min(0.95, 0.55 + 0.1 * sup.length - 0.1 * not.length),
      reason: 'support words: ' + sup.join(', ') };
  }
  return { category: 'support', intent: 'unclear', handoff: false, confidence: 0.3,
    reason: 'no rule matched' };
}

// What happens next, decided in one place from a classification.
//   route: 'not_support' | 'person' | 'answer'
function decideRoute(c, cfg) {
  if (c.category === 'not_support' && c.confidence >= cfg.min_classify_confidence) {
    return { route: 'not_support', route_reason: c.reason };
  }
  if (c.handoff || cfg.handoff_intents.includes(c.intent)) {
    return { route: 'person', route_reason: 'needs a person: ' + c.intent + ' (' + c.reason + ')' };
  }
  if (c.confidence < cfg.min_classify_confidence) {
    return { route: 'person', route_reason: 'classifier unsure (' + c.confidence + ' < '
      + cfg.min_classify_confidence + '): ' + c.reason };
  }
  return { route: 'answer', route_reason: c.reason };
}
const cfg = $('config').first().json;
const INTENTS = ['question', 'access', 'billing', 'complaint', 'refund', 'legal', 'cancellation', 'other'];

return $input.all().map((item, idx) => {
  const email = Object.assign({}, $('build the classification request').itemMatching(idx).json);
  delete email._body;
  const res = item.json || {};

  let c = null;
  let why = '';
  if (res.error) why = 'AI call failed: ' + String(res.error.message || res.error).slice(0, 160);
  else {
    try {
      const raw = res.choices && res.choices[0] && res.choices[0].message && res.choices[0].message.content;
      const p = JSON.parse(raw);
      const conf = Number(p.confidence);
      if (!['support', 'not_support'].includes(p.category)) why = 'AI answer had no valid category';
      else if (!(conf >= 0 && conf <= 1)) why = 'AI answer had no valid confidence';
      else c = { category: p.category, intent: INTENTS.includes(p.intent) ? p.intent : 'other',
        handoff: p.handoff === true, confidence: Math.round(conf * 100) / 100,
        reason: String(p.reason || '').slice(0, 200) };
    } catch (e) { why = 'AI answer did not parse'; }
  }

  const by = c ? 'AI (' + cfg.openai_chat_model + ')' : 'keyword rules (' + why + ')';
  if (!c) c = keywordClassify(email, cfg);
  return { json: Object.assign(email, c, decideRoute(c, cfg), { classified_by: by }) };
});

// The keyword classifier. With USE_OPENAI = false it IS the classifier; with it on, the same
// rules are the fallback inside `apply the AI classification` when the model fails.
//
// Output is the same typed shape the model is asked for:
//   category    'support' | 'not_support'
//   intent      short label: question, access, billing, complaint, refund, legal, ...
//   handoff     true when a person must answer, whatever the knowledge says
//   confidence  0..1
//   reason      one line a person can read
// plus `route` ('not_support' | 'person' | 'answer'), decided by the shared rule below.
// lib-classify.js: the keyword rules and the decision that reads a classification.
// Inlined by build.js into every node that classifies, so the keyword path and the AI
// fallback can never disagree.
function keywordClassify(email, cfg) {
  const t = ' ' + (email.subject + ' ' + email.body).toLowerCase().replace(/\s+/g, ' ') + ' ';
  const hits = (list) => list.filter((w) => t.indexOf(w.toLowerCase()) !== -1);
  const sup = hits(cfg.support_words);
  const not = hits(cfg.not_support_words);
  const hand = hits(cfg.handoff_words);

  let intent = 'question';
  if (hand.some((w) => /refund|chargeback/.test(w))) intent = 'refund';
  else if (hand.some((w) => /lawyer|legal/.test(w))) intent = 'legal';
  else if (hand.some((w) => /cancel|terminate/.test(w))) intent = 'cancellation';
  else if (hand.length) intent = 'complaint';
  else if (sup.some((w) => /password|login|log in|access|reset/.test(w))) intent = 'access';
  else if (sup.some((w) => /invoice|billing|payment/.test(w))) intent = 'billing';

  if (hand.length) {
    return { category: 'support', intent, handoff: true, confidence: 0.9,
      reason: 'handoff words: ' + hand.join(', ') };
  }
  if (not.length > sup.length) {
    return { category: 'not_support', intent: 'other', handoff: false,
      confidence: Math.min(0.95, 0.6 + 0.1 * (not.length - sup.length)),
      reason: 'not-support words: ' + not.join(', ') };
  }
  if (sup.length) {
    return { category: 'support', intent, handoff: false,
      confidence: Math.min(0.95, 0.55 + 0.1 * sup.length - 0.1 * not.length),
      reason: 'support words: ' + sup.join(', ') };
  }
  return { category: 'support', intent: 'unclear', handoff: false, confidence: 0.3,
    reason: 'no rule matched' };
}

// What happens next, decided in one place from a classification.
//   route: 'not_support' | 'person' | 'answer'
function decideRoute(c, cfg) {
  if (c.category === 'not_support' && c.confidence >= cfg.min_classify_confidence) {
    return { route: 'not_support', route_reason: c.reason };
  }
  if (c.handoff || cfg.handoff_intents.includes(c.intent)) {
    return { route: 'person', route_reason: 'needs a person: ' + c.intent + ' (' + c.reason + ')' };
  }
  if (c.confidence < cfg.min_classify_confidence) {
    return { route: 'person', route_reason: 'classifier unsure (' + c.confidence + ' < '
      + cfg.min_classify_confidence + '): ' + c.reason };
  }
  return { route: 'answer', route_reason: c.reason };
}
const cfg = $('config').first().json;
return $input.all().map((i) => {
  const c = keywordClassify(i.json, cfg);
  return { json: Object.assign({}, i.json, c, decideRoute(c, cfg), { classified_by: 'keyword rules' }) };
});

// Not a support request: sales pitches, newsletters, partnership offers. Routed out of the
// workflow here, by name, with the classifier's reason. Nothing is sent and the email is left
// in the inbox for whoever normally reads it.
return $input.all().map((i) => ({ json: {
  outcome: 'not a support email: left in the inbox',
  from: i.json.from,
  subject: i.json.subject,
  classified_by: i.json.classified_by,
  confidence: i.json.confidence,
  reason: i.json.route_reason
} }));

// One embeddings request per email: the subject and the new text of the body, with the same
// model the knowledge base was loaded with (workflow 02). A different model here would compare
// vectors from two different spaces and every score would be meaningless.
const cfg = $('config').first().json;
return $input.all().map((i) => ({ json: Object.assign({}, i.json, {
  _body: {
    model: cfg.openai_embed_model,
    input: (i.json.subject + '\n\n' + i.json.body).slice(0, 8000),
    dimensions: cfg.embed_dimensions
  }
}) }));

// Pairs each embedding back to its email and builds the Pinecone query. An email whose
// embedding failed (after the node's retries) is marked `embedded: false` with the API's own
// message, and `question embedded?` sends it to a person instead of querying with nothing.
const cfg = $('config').first().json;

return $input.all().map((item, idx) => {
  const email = Object.assign({}, $('build the embedding request').itemMatching(idx).json);
  delete email._body;
  const res = item.json || {};
  const vector = res.data && res.data[0] && res.data[0].embedding;

  if (res.error || !Array.isArray(vector) || !vector.length) {
    const why = res.error ? String(res.error.message || res.error).slice(0, 200) : 'no embedding in the response';
    return { json: Object.assign(email, {
      embedded: false,
      knowledge_ok: false,
      knowledge_reason: 'knowledge search failed: OpenAI embeddings - ' + why
    }) };
  }
  return { json: Object.assign(email, {
    embedded: true,
    _body: { vector, topK: cfg.top_k, includeMetadata: true, includeValues: false,
      namespace: cfg.pinecone_namespace }
  }) };
});

// Reads Pinecone's matches back onto each email and applies the knowledge gate: the best
// match must score at least MIN_MATCH_SCORE, or the email goes to a person. A failed query
// (after the node's retries) is the same outcome with the API's message on it: no knowledge,
// no automated answer.
//
// Workflow 02 stores the chunk text, its title and its source under `metadata`, which is what
// the reply is written from.
const cfg = $('config').first().json;

return $input.all().map((item, idx) => {
  const email = Object.assign({}, $('build the Pinecone query').itemMatching(idx).json);
  delete email._body;
  const res = item.json || {};

  if (res.error || !Array.isArray(res.matches)) {
    const why = res.error ? String(res.error.message || res.error).slice(0, 200) : 'no matches array in the response';
    return { json: Object.assign(email, { retrieved_from: 'Pinecone', matches: [], top_score: 0,
      match_floor: cfg.min_match_score, knowledge_ok: false,
      knowledge_reason: 'knowledge search failed: Pinecone - ' + why }) };
  }

  const matches = res.matches.map((m) => ({
    id: m.id,
    title: (m.metadata && m.metadata.title) || m.id,
    text: (m.metadata && m.metadata.text) || '',
    source: (m.metadata && m.metadata.source) || '',
    score: Math.round(Number(m.score || 0) * 1000) / 1000
  })).filter((m) => m.text).sort((a, b) => b.score - a.score);

  const top = matches.length ? matches[0].score : 0;
  const ok = top >= cfg.min_match_score;
  return { json: Object.assign(email, {
    retrieved_from: 'Pinecone (' + cfg.pinecone_namespace + ')',
    matches,
    top_score: top,
    match_floor: cfg.min_match_score,
    knowledge_ok: ok,
    knowledge_reason: ok
      ? 'best match "' + matches[0].title + '" scored ' + top
      : (matches.length ? 'not enough knowledge: best match scored ' + top + ', below the floor of ' + cfg.min_match_score
        : 'not enough knowledge: the index returned nothing for this question')
  }) };
});

// Stands in for OpenAI embeddings + Pinecone when they are not configured, so the whole run
// (retrieve, gate on the score, answer or escalate) can be watched with nothing connected.
//
// The score is coverage: the share of the email's content words found in a knowledge entry,
// 0..1. It is cruder than vector similarity and has its own floor, DEMO_MIN_MATCH_SCORE. The
// point it demonstrates is the gate, not the ranking.
const cfg = $('config').first().json;

const STOP = new Set(('the a an and or but to of in on for with at by from is are was were be been it this that '
  + 'i we you they he she my our your their me us hi hello thanks thank please can could would should do does did '
  + 'how what when where why who re fw fwd have has had not no yes will just about there here some any all get got '
  + 'com org net co uk example').split(' '));
const stem = (w) => w.replace(/(ing|ed|es|s)$/, '');
function words(text) {
  return new Set(String(text).toLowerCase().replace(/[^a-z0-9\s]/g, ' ').split(/\s+/)
    .filter((w) => w.length > 2 && !STOP.has(w)).map(stem));
}

const kb = cfg.demo_knowledge.map((d) => ({ id: d.id + '#0', title: d.title, text: d.text,
  words: words(d.title + ' ' + d.text) }));

return $input.all().map((i) => {
  const q = words(i.json.subject + ' ' + i.json.body);
  const matches = kb.map((d) => {
    let hit = 0;
    for (const w of q) if (d.words.has(w)) hit++;
    return { id: d.id, title: d.title, text: d.text, score: q.size ? Math.round((hit / q.size) * 100) / 100 : 0 };
  }).sort((a, b) => b.score - a.score).slice(0, cfg.top_k);

  const top = matches.length ? matches[0].score : 0;
  const floor = cfg.demo_min_match_score;
  return { json: Object.assign({}, i.json, {
    retrieved_from: 'demo knowledge base (word overlap)',
    matches,
    top_score: top,
    match_floor: floor,
    knowledge_ok: top >= floor,
    knowledge_reason: top >= floor
      ? 'best match "' + matches[0].title + '" scored ' + top
      : 'not enough knowledge: best match scored ' + top + ', below the floor of ' + floor
  }) };
});

// One OpenAI chat request per email. The model is given the customer's email and the
// retrieved knowledge excerpts, and nothing else, and is told to answer only from them.
// If the excerpts do not answer the question it must say so, and `apply the AI reply` sends
// the email to a person rather than letting a guess go out.
const cfg = $('config').first().json;

const system = [
  'You write email replies for the customer support desk of ' + cfg.company_name + '.',
  'Answer ONLY from the knowledge excerpts provided. Do not use outside knowledge, and do not',
  'promise refunds, discounts, dates or prices that the excerpts do not state.',
  'If the excerpts do not contain what is needed to answer, set "escalate" to true and leave "reply" empty.',
  'Write plain text, friendly and brief (under 170 words), greet the customer by first name if known,',
  'and sign off as: ' + cfg.signature,
  'Answer with a JSON object only: {"reply": string, "used_sources": [ids of the excerpts you used],',
  '"escalate": boolean, "reason": string}'
].join('\n');

return $input.all().map((i) => {
  const excerpts = i.json.matches.filter((m) => m.score >= i.json.match_floor / 2)
    .map((m) => '[' + m.id + '] ' + m.title + '\n' + m.text).join('\n\n');
  return { json: Object.assign({}, i.json, {
    _body: {
      model: cfg.openai_chat_model,
      temperature: 0.2,
      response_format: { type: 'json_object' },
      messages: [
        { role: 'system', content: system },
        { role: 'user', content: 'KNOWLEDGE EXCERPTS\n\n' + excerpts
          + '\n\nCUSTOMER EMAIL\nFrom: ' + (i.json.from_name || i.json.from)
          + '\nSubject: ' + i.json.subject + '\n\n' + i.json.body.slice(0, 6000) }
      ]
    }
  }) };
});

// Pairs each drafted reply back to its email and decides whether it may be sent. It may not
// when: the call failed after its retries, the answer does not parse, the model asked to
// escalate, the reply is empty, or it claims a source that was not among the excerpts it was
// given. Each of those goes to a person with the reason, and the draft (if any) is attached so
// the person starts from it.
return $input.all().map((item, idx) => {
  const email = Object.assign({}, $('build the reply request').itemMatching(idx).json);
  delete email._body;
  const res = item.json || {};
  const given = new Set(email.matches.map((m) => m.id));

  let reply = '';
  let used = [];
  let problem = '';
  if (res.error) problem = 'reply generation failed: ' + String(res.error.message || res.error).slice(0, 200);
  else {
    try {
      const p = JSON.parse(res.choices[0].message.content);
      reply = String(p.reply || '').trim();
      used = Array.isArray(p.used_sources) ? p.used_sources.map(String) : [];
      if (p.escalate === true) problem = 'the model said the knowledge does not answer it: ' + String(p.reason || '').slice(0, 160);
      else if (!reply) problem = 'the model returned an empty reply';
      else if (!used.length) problem = 'the reply cites no knowledge source';
      else if (used.some((u) => !given.has(u))) problem = 'the reply cites a source it was not given: ' + used.filter((u) => !given.has(u)).join(', ');
    } catch (e) { problem = 'the reply did not parse'; }
  }

  return { json: Object.assign(email, {
    reply_text: reply,
    used_sources: used,
    written_by: 'AI (' + $('config').first().json.openai_chat_model + ')',
    reply_ok: problem === '',
    reply_problem: problem
  }) };
});

// With USE_OPENAI = false there is no model to write the reply, so it is assembled from the
// best-matching knowledge entry with a fixed template. It is plainer than a written answer,
// and every sentence in it is from the knowledge base, which is the property that matters.
const cfg = $('config').first().json;

return $input.all().map((i) => {
  const best = i.json.matches[0];
  const first = String(i.json.from_name || '').split(/\s+/)[0] || 'there';
  const reply = [
    'Hi ' + first + ',',
    '',
    'Thanks for getting in touch. ' + best.text,
    '',
    'If that does not sort it out, just reply to this email and someone from the team will pick it up.',
    '',
    cfg.signature
  ].join('\n');
  return { json: Object.assign({}, i.json, {
    reply_text: reply,
    used_sources: [best.id],
    written_by: 'template, from the knowledge base',
    reply_ok: true,
    reply_problem: ''
  }) };
});

// Decides where each reply goes, in one place:
//   live    -> a reply on the customer's own Gmail message, so it stays in their thread
//   test    -> a new email to TEST_EMAIL, marked [TEST], saying which thread it would have
//              gone into; at most TEST_CAP per run
//   preview -> nowhere; the reply is shown on STOP: preview - reply not sent
// REPLY_CAP_PER_RUN is enforced here. Anything over it is held, with the reason, on
// STOP: preview - reply not sent, for a person to answer. The trigger only picks up new mail.
const cfg = $('config').first().json;
const cap = cfg.mode === 'test' ? Math.min(cfg.test_cap, cfg.reply_cap_per_run) : cfg.reply_cap_per_run;

return $input.all().map((i, idx) => {
  const e = i.json;
  const held = idx >= cap;
  const out = Object.assign({}, e, {
    mode: cfg.mode,
    live: cfg.mode === 'live',
    held_by_cap: held,
    hold_reason: held ? 'over the ' + cfg.mode + ' cap of ' + cap + ' replies per run' : '',
    // Thread continuity: the live reply is attached to message_id (Gmail's id), which puts it in
    // thread_id and sets In-Reply-To / References from the original's RFC Message-ID.
    reply_to_message_id: e.message_id,
    reply_thread_id: e.thread_id,
    reply_in_reply_to: e.rfc_message_id,
    reply_subject: /^re:/i.test(e.subject) ? e.subject : 'Re: ' + e.subject
  });
  if (cfg.mode === 'test') {
    out.test_to = cfg.test_email;
    out.test_subject = '[TEST] ' + out.reply_subject;
    out.test_body = 'Would reply to ' + e.from + ' in thread ' + e.thread_id + ' (message ' + e.message_id + ').\n'
      + 'Classified by ' + e.classified_by + ' as ' + e.intent + ' (' + e.confidence + '). '
      + e.knowledge_reason + '. Written by ' + e.written_by + '.\n\n----\n\n' + e.reply_text;
  }
  return { json: out };
});

// Preview mode (TEST_RUN = true, TEST_EMAIL blank), or over the per-run cap. The reply is
// built in full and shown here, exactly as the customer would get it, and nothing is sent.
// Read these before switching anything on.
const cfg = $('config').first().json;
return $input.all().map((i) => ({ json: {
  outcome: i.json.held_by_cap ? 'held: ' + i.json.hold_reason : 'preview: reply not sent (mode ' + cfg.mode + ')',
  to: i.json.from,
  subject: i.json.reply_subject,
  would_reply_to_message: i.json.reply_to_message_id,
  thread_id: i.json.reply_thread_id,
  in_reply_to: i.json.reply_in_reply_to,
  classified_by: i.json.classified_by,
  knowledge: i.json.knowledge_reason,
  sources: i.json.used_sources,
  written_by: i.json.written_by,
  reply: i.json.reply_text
} }));

// Live: the reply went out on the customer's own message, so Gmail kept it in their thread.
// The ids Gmail returned are listed beside the ones the reply was attached to, so a reply that
// landed in a new thread would be visible here.
return $input.all().map((i, idx) => {
  const sent = $('address the reply').itemMatching(idx).json;
  return { json: {
    outcome: 'replied in the thread',
    to: sent.from,
    subject: sent.reply_subject,
    thread_id: sent.reply_thread_id,
    gmail_thread_id: i.json.threadId || '',
    same_thread: !i.json.threadId || i.json.threadId === sent.reply_thread_id,
    gmail_message_id: i.json.id || '',
    sources: sent.used_sources
  } };
});

// Test mode: the reply went to TEST_EMAIL as a new email marked [TEST], carrying the thread it
// would have joined. Nothing reached the customer.
return $input.all().map((i, idx) => {
  const sent = $('address the reply').itemMatching(idx).json;
  return { json: {
    outcome: 'test copy sent to ' + sent.test_to,
    would_reply_to: sent.from,
    thread_id: sent.reply_thread_id,
    gmail_message_id: i.json.id || ''
  } };
});

// Gmail refused a send after the node's retries: a reply, a test copy or an escalation alert.
// Gmail's own error is kept on the item so the cause is readable (expired credential, a
// deleted message, a quota). The customer has not been answered: a person picks it up here.
return $input.all().map((i) => ({ json: {
  outcome: 'Gmail refused the send',
  error: (i.json.error && (i.json.error.message || i.json.error)) || i.json.message || 'unknown error',
  detail: i.json.error && i.json.error.description ? i.json.error.description : ''
} }));

// Everything the workflow will not answer on its own ends here: a handoff intent, a classifier
// that was unsure, not enough knowledge, a failed knowledge search, or a reply that could not
// be trusted. The support team gets one email per case with the reason, the customer's words,
// what was retrieved and the draft if there was one, so nobody starts from nothing.
//
// Nothing is sent to the customer from this path. The email stays in their inbox thread for a
// person to answer.
const cfg = $('config').first().json;

return $input.all().map((i, idx) => {
  const e = i.json;
  const reason = e.route === 'person' ? e.route_reason
    : (e.knowledge_ok === false ? e.knowledge_reason
    : (e.reply_ok === false ? e.reply_problem : 'needs a person'));

  const matches = (e.matches || []).slice(0, 3)
    .map((m) => '- ' + m.title + ' (score ' + m.score + ')').join('\n') || '- none';
  const body = [
    'This support email needs a person. It has NOT been answered.',
    '',
    'Why: ' + reason,
    'From: ' + (e.from_name ? e.from_name + ' <' + e.from + '>' : e.from),
    'Subject: ' + e.subject,
    'Classified by ' + (e.classified_by || '-') + ' as ' + (e.intent || '-') + ' (confidence ' + (e.confidence ?? '-') + ')',
    'Open the thread: https://mail.google.com/mail/u/0/#all/' + e.thread_id,
    '',
    'Their message:',
    e.body,
    '',
    'Knowledge retrieved:',
    matches,
    e.reply_text ? '\nDraft that was not sent:\n' + e.reply_text : ''
  ].join('\n');

  const test = cfg.mode === 'test';
  return { json: {
    escalation_reason: reason,
    from: e.from,
    subject: e.subject,
    thread_id: e.thread_id,
    message_id: e.message_id,
    alert_to: test ? cfg.test_email : cfg.support_team_email,
    alert_subject: (test ? '[TEST] ' : '') + '[Needs a person] ' + e.subject,
    alert_body: body,
    held_by_cap: test && idx >= cfg.test_cap
  } };
});

// The support team has the case, with the reason, the customer's words, what was retrieved
// and any draft. The customer has not been answered automatically.
return $input.all().map((i, idx) => {
  const sent = $('prepare the escalation').itemMatching(idx).json;
  return { json: {
    outcome: 'escalated to ' + sent.alert_to,
    reason: sent.escalation_reason,
    from: sent.from,
    subject: sent.subject,
    thread_id: sent.thread_id
  } };
});

// Preview mode, no SUPPORT_TEAM_EMAIL, or over the test cap: the escalation alert is built in
// full and shown here, and nothing is sent. In every case the customer's email is left
// unanswered for a person.
const cfg = $('config').first().json;
return $input.all().map((i) => ({ json: {
  outcome: i.json.held_by_cap ? 'held: over the test cap'
    : (cfg.mode === 'preview' ? 'preview: escalation not sent' : 'no SUPPORT_TEAM_EMAIL: escalation not sent'),
  reason: i.json.escalation_reason,
  would_alert: i.json.alert_to || '(nobody configured)',
  alert_subject: i.json.alert_subject,
  alert_body: i.json.alert_body
} }));
